function exportJSON() {
    if (!archive.length) {
      setStatus('Архив пуст — нечего выгружать.');
      return;
    }
    const blob = new Blob([JSON.stringify(archive, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'capcut_vectors.json';
    a.click();
    URL.revokeObjectURL(url);
    setStatus('Файл capcut_vectors.json скачан. Перенеси его в D:\\Projects\\reality-1 для git push.');
  }

function copyText(idx) {
    navigator.clipboard.writeText(archive[idx].content);
